import*as THREE from'three';import{materials}from'../../core/index.js';import{addCadParts}from'../../modeling/cad.js';import{mesh,slab}from'../../modeling/parts.js';import{spec}from'./dimensions.js';import{grove,terminal}from'./connectors.js';import{TerminalPlug}from'./TerminalPlug.js';import{addStickers}from'./stickers.js';import data from'./geometry-data.js';const tau=Math.PI*2;
function solid(p,s,d,at,m,n){return mesh(p,new THREE.ExtrudeGeometry(s,{depth:d,bevelEnabled:false,curveSegments:40}),m,at,n);}
function annulus(p,outer,inner,d,at,m,n){const s=new THREE.Shape();s.absarc(0,0,outer,0,tau,false);const h=new THREE.Path();h.absarc(0,0,inner,0,tau,false);s.holes.push(h);return solid(p,s,d,at,m,n);}
function board(host){const s=new THREE.Shape(),x=10.2,r=3.7,row=-16,angle=Math.acos((x-8)/r),dy=Math.sqrt(r*r-(x-8)**2);s.moveTo(-5.5,-26.2);s.lineTo(-8.4,-26.2);s.lineTo(-x,-24.4);s.lineTo(-x,row-dy);s.absarc(-8,row,r,Math.PI+angle,Math.PI-angle,false);s.lineTo(-x,22.8);s.lineTo(-8.8,24.0);s.lineTo(8.8,24.0);s.lineTo(x,22.8);s.lineTo(x,row+dy);s.absarc(8,row,r,angle,tau-angle,false);s.lineTo(x,-24.4);s.lineTo(8.4,-26.2);s.lineTo(5.5,-26.2);s.lineTo(5.5,-21.5);s.lineTo(-5.5,-21.5);s.closePath();const holes=[[0,-16,1.8],...[-3,-1,1,3].map(x=>[x,-20.2,.48]),...spec.terminal.pinX.map(x=>[x,18.5,.55])];for(const[x,y,r]of holes){const h=new THREE.Path();h.absarc(x,y,r,0,tau,false);s.holes.push(h);}const green=materials.plastic(0x346247,{roughness:.9}),tin=materials.metal(0xb7bdad,{roughness:.5}),dark=materials.plastic(0x1d241e,{roughness:.88}),ceramic=materials.plastic(0xb9ac85,{roughness:.9}),pcb=solid(host.body,s,.8,[0,0,-1.6],green,'SSR own reconstructed populated carrier PCB with actual mount reliefs retaining and eight solder bores'),pads=[],barrels=[];pcb.userData={role:'physical-pcb',installationInferred:true};for(const[x,y,r]of holes.slice(1)){const inner=y>0?.38:.34,outer=y>0?.8:.7;pads.push(annulus(host.body,outer,inner,.06,[x,y,-.8],tin,'SSR actual plated annular solder land'));barrels.push(annulus(host.body,r,inner,.8,[x,y,-1.6],tin,'SSR actual inner plated solder barrel'));}
 const opto=slab(host.body,6.5,7.3,3.0,.2,[0,2.8,-.8],dark,[],.025);opto.name='SSR U1 actual six-terminal MOC3043M optocoupler package,installation inferred';const optoMark=mesh(host.body,new THREE.CylinderGeometry(.32,.32,.025,24).rotateX(Math.PI/2),materials.plastic(0x5a625a),[-2.2,5.2,2.213],'SSR MOC3043M real package pin-one indentation appearance');const optoLeads=[];for(const sign of[-1,1])for(const dy of[-2.54,0,2.54]){const lead=new THREE.Group();lead.name='SSR MOC3043M actual formed solder lead';host.body.add(lead);mesh(lead,new THREE.BoxGeometry(1.5,.55,.18),tin,[sign*3.7,2.8+dy,.15],'SSR optocoupler retained outward lead');mesh(lead,new THREE.BoxGeometry(.35,.55,.85),tin,[sign*4.3,2.8+dy,-.3],'SSR optocoupler actual downward lead');mesh(lead,new THREE.BoxGeometry(.65,.55,.12),tin,[sign*4.45,2.8+dy,-.74],'SSR optocoupler PCB solder foot');optoLeads.push(lead);}
 const triac=slab(host.body,6.5,6.1,2.2,.12,[0,12.8,-.8],dark,[],.025);triac.name='SSR Q1 actual BT136S power semiconductor DPAK appearance';const triacTab=mesh(host.body,new THREE.BoxGeometry(5.3,3.0,.25),tin,[0,16.1,-.66],'SSR BT136S fixed metal thermal tab,no invented mounting bore'),triacLeads=[];for(const x of[-2.3,0,2.3])triacLeads.push(mesh(host.body,new THREE.BoxGeometry(.8,2.1,.22),tin,[x,9.5,-.69],'SSR BT136S actual fixed terminal envelope'));
 const q2=slab(host.body,1.6,2.9,1.1,.09,[-5.9,-6.4,-.8],dark,[],.015);q2.name='SSR Q2 actual SS8050 transistor package';const q2Leads=[];for(const[dx,dy]of[[-1.05,-.9],[-1.05,.9],[1.05,0]])q2Leads.push(mesh(host.body,new THREE.BoxGeometry(.65,.45,.15),tin,[-5.9+dx,-6.4+dy,-.72],'SSR SS8050 real terminal'));
 const fuse=slab(host.body,6.1,2.54,2.5,.12,[6.7,14.6,-.8],materials.plastic(0xe3dfcb,{roughness:.86}),[],.02);fuse.name='SSR F1 actual2410 fixed fuse package';for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.55,2.54,.28),tin,[6.7+sign*2.8,14.6,-.66],'SSR fuse metal end cap');const clamp=slab(host.body,3.2,2.5,1.05,.1,[6.2,6.6,-.8],ceramic,[],.015);clamp.name='SSR R4 actual1210 fixed clamp package';const capacitor=slab(host.body,4.5,2.4,2.0,.1,[-6.3,12.3,-.8],ceramic,[],.02);capacitor.name='SSR C1 actual fixed high-voltage capacitor envelope,package size inferred';const resistors=[];for(const[name,x,y]of[['R1',-5.8,-1.8],['R2',-5.8,8.0],['R3',-7.1,17.6],['R5',5.4,9.4],['R6',-2.8,-7.4],['R7',-.6,-7.4],['R8',5.5,-5.7]]){const q=slab(host.body,1.6,.8,.6,.05,[x,y,-.8],dark,[],.01);q.name='SSR actual '+name+' resistor package,installed pose inferred';resistors.push(q);for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.25,.8,.12),tin,[x+sign*.68,y,-.73],'SSR actual resistor solder end');}const indicator=slab(host.body,1.6,.8,.55,.04,[5.7,-9.2,-.8],materials.plastic(0xa24e45,{roughness:.92}),[],.01);indicator.name='SSR actual internal D1 red0603 fixed nonemissive package,no established exterior optical path';for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.25,.8,.12),tin,[5.7+sign*.68,-9.2,-.73],'SSR D1 actual fixed solder end');return{pcb,holes,pads,barrels,opto,optoMark,optoLeads,triac,triacTab,triacLeads,q2,q2Leads,fuse,clamp,capacitor,resistors,indicator};}
function fixing(host){const s=new THREE.Shape();s.absarc(0,0,1.5,0,tau,false);const h=new THREE.Path();for(let i=0;i<6;i++){const a=i*tau/6;if(i)h.lineTo(.6*Math.cos(a),.6*Math.sin(a));else h.moveTo(.6*Math.cos(a),.6*Math.sin(a));}h.closePath();s.holes.push(h);const tin=materials.metal(0xb0baac,{roughness:.45}),head=solid(host.body,s,.42,spec.screw.position,tin,'SSR actual fixed rear retaining screw with true annular hex head'),blind=mesh(host.body,new THREE.CylinderGeometry(.6,.6,.12,6).rotateX(Math.PI/2),materials.metal(0x5c665b),[0,-16,-3.47],'SSR actual retaining screw blind hex floor'),shank=mesh(host.body,new THREE.CylinderGeometry(.6,.6,4.8,32).rotateX(Math.PI/2),tin,[0,-16,-.9],'SSR actual fixed rear retaining shank');return{head,blind,shank};}
export function buildSSR(host,{terminalPlug=false}={}){if(typeof terminalPlug!=='boolean')throw new TypeError('terminalPlug must be boolean');const parts=addCadParts(host,data,{shell:materials.plastic(0xe7e9e2,{roughness:.86})}),pcb=board(host),input=grove(host),output=terminal(host),screw=fixing(host),labels={};for(const face of['front','back']){const v=spec.labels[face],p=slab(host.body,...v.size,face==='front'?.05:.04,.4,v.position,materials.plastic(0xe8ebe5,{roughness:.89}),[],.005);p.name='SSR real '+face+' body adhesive film';p.userData={role:'physical-label-substrate',face};labels[face]=p;}host.ssrAssembly={parts,pcb,input,output,screw,labels};host.unitStickers=addStickers(host);if(terminalPlug)output.port.attach(new TerminalPlug());}
